def M(s):return r'\('+s+r'\)'
def bi(k,e=None):return {'ko':k,'en':k if e is None else e}
def calc(q,eq,tk,te,lines,ans,k='',e='',sub=''):
 p=856 if q<=32 else 857 if q<=38 else 858
 steps=[M(t)for t in lines];ek=steps+([k]if k else[]);ee=steps+([e]if e else[])
 items.append(dict(id=f'stewart9-exercise-11.11-{q}',number=q,subparts=list(sub),source=dict(printedPage=p,pdfPage=p+37),topic=bi('테일러 다항식의 응용','Applications of Taylor polynomials'),statement=bi(M(eq)+' '+tk,M(eq)+' '+te),hint=bi('중심에서 도함수를 구하고 다음 도함수의 상계나 교대급수의 첫 생략항으로 나머지를 제어한다.','Compute derivatives at the center and control the remainder by a derivative bound or the first omitted alternating term.'),steps=bi(ek,ee),answer=bi(M(ans)),check=bi('도함수 계수와 나머지 부등식의 가정을 확인하고 수치값을 독립 대조했다.','Derivative coefficients and remainder hypotheses were checked, with numerical values independently compared.'),conceptHref='../../calc1/index.html',status='math-verified'))
def poly(f,a,n):return S.expand(sum(S.simplify(S.diff(f,x,j).subs(x,a))*h**j/S.factorial(j)for j in range(n+1)))
def plt(q,curves,xlim,ylim,caption=None):
 xa,xb=map(float,xlim);ya,yb=map(float,ylim);X=lambda z:60+555*(z-xa)/(xb-xa);Y=lambda z:345-300*(z-ya)/(yb-ya)
 out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 660 470"><defs><clipPath id="v"><rect x="60" y="45" width="555" height="300"/></clipPath></defs><rect width="660" height="470" fill="white"/>']
 out.append(f'<path d="M60 {Y(max(ya,min(yb,0)))}H615M{X(max(xa,min(xb,0)))} 45V345" stroke="#9aa5b2" fill="none"/>')
 for j,(name,fn)in enumerate(curves):
  c=['#152238','#d5553c','#147cc1','#23865f','#9556b0','#b17b23'][j%6];points=[]
  for i in range(601):
   z=xa+(xb-xa)*i/600;v=float(fn(z));assert math.isfinite(v);points.append(f'{X(z):.3f},{Y(v):.3f}')
  out.append(f'<polyline points="{" ".join(points)}" fill="none" stroke="{c}" stroke-width="2.1" clip-path="url(#v)"/><text x="65" y="{390+15*j}" fill="{c}" font-size="12">{html.escape(name)}</text>')
 for i in range(5):
  z=xa+(xb-xa)*i/4;v=ya+(yb-ya)*i/4;out.append(f'<text x="{X(z)-12}" y="367" font-size="11">{z:.4g}</text><text x="3" y="{Y(v)+4}" font-size="11">{v:.4g}</text>')
 out.append('</svg>');path=BASE/f'exercise-content/assets/s11-11-{q}.svg';path.write_text(''.join(out));ex=next(t for t in items if t['number']==q);ex['figure']={'src':f'../exercise-content/assets/{path.name}','alt':bi('함수·테일러 근사 또는 실제 절대오차의 자체 그래프','Original plot of the function, Taylor approximations, or actual absolute error'),'caption':caption or bi('표시한 식을 직접 계산한 그래프. 오차 상계의 증명은 풀이에 있다.','Plots computed directly from the displayed formulas. The solution proves each error bound.')}
for q,f,degrees,points,xlim,ylim in [(1,S.sin(x),[0,1,3,5],[S.pi/4,S.pi/2,S.pi],[-4,4],[-3,3]),(2,S.tan(x),[0,1,3],[S.pi/6,S.pi/4,S.pi/3],[-1.3,1.3],[-4,4])]:
 ps={j:poly(f,0,j).subs(h,x)for j in degrees};lines=[rf'T_{{{j}}}(x)={S.latex(p)}'for j,p in ps.items()]
 lines+=([r'T_2=T_1,\quad T_4=T_3']if q==1 else[r'T_2=T_1'])
 for z in points:lines.append(rf'x={S.latex(z)}:\quad f={float(f.subs(x,z)):.9f};\quad '+r',\quad '.join(rf'T_{{{j}}}={float(p.subs(x,z)):.9f}'for j,p in ps.items()))
 calc(q,'f(x)='+S.latex(f)+rf',\quad a=0,\quad n\le{max(degrees)},\quad x\in\{{'+','.join(S.latex(z)for z in points)+r'\}','(a) 지정 차수까지의 테일러 다항식과 함수 그래프 (b) 제시한 입력에서의 수치값 (c) 수렴 양상을 구하라.','Find (a) the Taylor polynomials through the given degree and a shared plot, (b) values at the stated inputs, and (c) a convergence description.',lines,r'T_n\to\sin x\text{ for all }x'if q==1 else r'T_n\to\tan x\quad(|x|<\pi/2)','사인 급수는 모든 유계 구간에서 균등 수렴하지만 먼 입력에는 더 높은 차수가 필요하다.'if q==1 else'원점의 탄젠트 급수는 가장 가까운 극점까지의 거리 안에서 수렴한다. 극점에 가까울수록 같은 정확도에 더 많은 항이 필요하다.','The sine series converges uniformly on every bounded interval; more distant inputs require higher degree.'if q==1 else'The tangent series converges up to the nearest poles. More terms are needed near a pole for a given accuracy.',sub='abc')
 plt(q,[('f',S.lambdify(x,f,'math'))]+[(f'T{j}',S.lambdify(x,p,'math'))for j,p in ps.items()],xlim,ylim)
