for q,f,a,xlim,ylim in rows:
 p=poly(f,a,3);calc(q,rf'f(x)={S.latex(f)},\quad a={S.latex(a)}','삼차 테일러 다항식을 구하고 함수와 함께 그려라.','Find the cubic Taylor polynomial and plot it together with the function.',[r'T_3(x)=\sum_{j=0}^3f^{(j)}(a)(x-a)^j/j!',rf'h=x-({S.latex(a)})',rf'(f(a),f^{{\prime}}(a),f^{{\prime\prime}}(a),f^{{(3)}}(a))={S.latex(S.Tuple(*[S.simplify(S.diff(f,x,j).subs(x,a))for j in range(4)]))}'],rf'T_3={S.latex(p)},\quad h=x-({S.latex(a)})');plt(q,[('f',S.lambdify(x,f,'math')),('T3',S.lambdify(x,p.subs(h,x-a),'math'))],xlim,ylim)
for q,f,a,xlim,ylim in [(11,S.cot(x),S.pi/4,[.18,1.45],[-1,6]),(12,(1+x*x)**S.Rational(1,3),S.Integer(0),[-1.5,1.5],[.6,2])]:
 ps={j:poly(f,a,j)for j in range(2,6)};calc(q,rf'f(x)={S.latex(f)},\quad a={S.latex(a)}','컴퓨터 대수로 2차부터 5차까지 테일러 다항식을 구하고 함수와 함께 그려라.','Use a computer algebra system to find Taylor polynomials of degrees two through five and plot them with the function.',[r'T_n=\sum_{j=0}^n f^{(j)}(a)h^j/j!,\quad h=x-a']+[rf'T_{{{j}}}={S.latex(p)}'for j,p in ps.items()],r';\quad '.join(rf'T_{{{j}}}={S.latex(p)}'for j,p in ps.items())+rf',\quad h=x-({S.latex(a)})','SymPy로 도함수 계수를 계산하고 독립 급수 전개와 대조했다.','SymPy derivative coefficients were compared with an independent series expansion.');plt(q,[('f',S.lambdify(x,f,'math'))]+[(f'T{j}',S.lambdify(x,p.subs(h,x-a),'math'))for j,p in ps.items()],xlim,ylim)
