boundrows=[(13,1/x,1,2,S.Rational(7,10),S.Rational(13,10),6/S.Rational(7,10)**4,'The magnitude 6/x^4 decreases.'),(14,x**S.Rational(-1,2),4,2,S.Rational(7,2),S.Rational(9,2),S.Rational(15,8)*S.Rational(7,2)**S.Rational(-7,2),'The magnitude (15/8)x^(-7/2) decreases.'),(15,x**S.Rational(2,3),1,3,S.Rational(4,5),S.Rational(6,5),S.Rational(56,81)*S.Rational(4,5)**S.Rational(-10,3),'The magnitude (56/81)x^(-10/3) decreases.'),(16,S.sin(x),S.pi/6,4,0,S.pi/3,1,'The absolute cosine is at most one.'),(17,S.sec(x),0,2,-S.Rational(1,5),S.Rational(1,5),thirdsec,'The absolute third derivative is increasing with |x| on this interval.'),(18,S.log(1+2*x),1,3,S.Rational(1,2),S.Rational(3,2),6,'The magnitude 96/(1+2x)^4 decreases.'),(19,S.exp(x*x),0,3,0,S.Rational(1,10),(12+48*S.Rational(1,100)+16*S.Rational(1,10000))*S.exp(S.Rational(1,100)),'The positive polynomial times exp(x^2) increases on this nonnegative interval.'),(20,x*S.log(x),1,3,S.Rational(1,2),S.Rational(3,2),16,'The magnitude 2/x^3 decreases.'),(21,x*S.sin(x),0,4,-1,1,6,'Use |x cos(x)+5 sin(x)| <= |x|+5 <= 6.'),(22,S.sinh(2*x),0,5,-1,1,64*S.sinh(2),'Use |64 sinh(2x)| <= 64 sinh(2).')]
for q,f,a,degree,lo,hi,bound,why in boundrows:
 p=poly(f,a,degree);rad=max(abs(S.sympify(lo)-a),abs(S.sympify(hi)-a));B=S.simplify(bound*rad**(degree+1)/S.factorial(degree+1));der=S.simplify(S.diff(f,x,degree+1))
 calc(q,rf'f(x)={S.latex(f)},\quad a={S.latex(a)},\quad n={degree},\quad {S.latex(lo)}\le x\le {S.latex(hi)}','(a) 지정 테일러 다항식 (b) 구간 전체에서의 테일러 부등식 오차 상계 (c) 절대오차 그래프를 구하라.','Find (a) the specified Taylor polynomial, (b) a Taylor-inequality error bound over the full interval, and (c) the absolute-error graph.',[rf'T_{{{degree}}}={S.latex(p)},\quad h=x-({S.latex(a)})',rf'f^{{({degree+1})}}(x)={S.latex(der)}',rf'|f^{{({degree+1})}}(x)|\le M={S.latex(bound)}',rf'|R_{{{degree}}}(x)|\le\frac{{M|x-a|^{{{degree+1}}}}}{{{degree+1}!}}\le {S.latex(B)}\approx {float(B):.10f}'],rf'T_{{{degree}}}={S.latex(p)},\ h=x-({S.latex(a)});\quad |R_{{{degree}}}|\le {S.latex(B)}','도함수의 단조성 또는 삼각함수의 절댓값 상계로 구간 전체의 상계를 얻는다. 그래프의 실제 오차는 보증 상계 이하이다.',why+' The plot shows the actual error below the certified bound.',sub='abc')
 fn=S.lambdify(x,f,'mpmath');pn=S.lambdify(x,p.subs(h,x-a),'mpmath');af=float(a);bf=float(bound)
 err=lambda z,fn=fn,pn=pn:float(abs(fn(mp.mpf(z))-pn(mp.mpf(z))))
 env=lambda z,af=af,bf=bf,degree=degree:bf*abs(z-af)**(degree+1)/math.factorial(degree+1)
 for z in [float(lo)+(float(hi)-float(lo))*i/300 for i in range(301)]:assert err(z)<=env(z)+1e-14
 plt(q,[('|f - Tn|',err),('Taylor bound M |x-a|^(n+1)/(n+1)!',env)],(lo,hi),(0,max(float(B)*1.05,1e-8)))
for q,f,a,z,n,err in [(23,S.cos(x),S.pi/2,4*S.pi/9,3,(S.pi/18)**5/120),(24,S.sin(x),S.pi/6,19*S.pi/90,4,(2*S.pi/45)**5/120)]:
 p=poly(f,a,n);v=S.N(p.subs(h,z-a),50);actual=S.N(f.subs(x,z),50);assert abs(v-actual)<err
 lo,hi=(v,v+err)if q==23 else(v-err,v+err);assert round(float(lo),5)==round(float(hi),5)
 calc(q,rf'{S.latex(f.subs(x,z))},\quad a={S.latex(a)}','앞 문항의 중심과 테일러 다항식을 사용하여 소수 다섯째 자리까지 구하고 정확도를 보증하라.','Use the earlier center and Taylor polynomial to compute five decimal places and certify the accuracy.',[rf'h={S.latex(z-a)},\quad T_{{{n}}}={S.latex(p)}',rf'T_{{{n}}}={float(v):.12f},\quad |R|\le {S.latex(err)}<{float(err)*1.0001:.12f}',rf'{float(lo):.12f}\le f\le {float(hi):.12f}'],rf'f\approx {float(v):.5f}','양쪽 경계가 모두 같은 다섯 자리 값으로 반올림된다. 코사인 문항은 중심 이동 후 사인 교대급수로 오차 부호까지 결정한다.','Both endpoints round to the same five-decimal value. In the cosine exercise, the shifted sine alternating series also determines the error sign.')
calc(25,r'e^{0.1},\quad \varepsilon=10^{-5}','테일러 부등식으로 충분한 매클로린 항 수를 정하라.','Use Taylor’s inequality to determine a sufficient number of Maclaurin terms.',[r'0\le t\le0.1:\quad e^t\le e^{0.1}',r'|R_n(0.1)|\le e^{0.1}(0.1)^{n+1}/(n+1)!',r'n=2:\quad e^{0.1}10^{-3}/6>10^{-5};\quad n=3:\quad e^{0.1}10^{-4}/24<4.61\times10^{-6}',r'T_3(0.1)=1+0.1+0.1^2/2+0.1^3/6'],r'4\text{ terms, through degree }3')
